export function TextControl({
  schema,
  field,
  textInput,
  compact,
  nullable,
  ...controlProps
}: {
  schema: Schema;
  field: ControlFieldApi;
  textInput?: JsonFormTextInput;
  compact: boolean;
  nullable: boolean;
} & ScalarControlDomProps) {
  const value = field.value == null ? "" : String(field.value);

  if (!compact && shouldRenderTextarea(schema, textInput)) {
    return (
      <Textarea
        {...controlProps}
        value={value}
        onChange={(event) =>
          field.onChange(
            event.target.value === "" && nullable ? null : event.target.value,
          )
        }
        onBlur={field.onBlur}
        name={field.name}
      />
    );
  }

  if (!compact) {
    return (
      <Input
        {...controlProps}
        value={value}
        onChange={(event) => {
          const nextValue = event.currentTarget.value;
          field.onChange(nextValue === "" && nullable ? null : nextValue);
        }}
        onBlur={field.onBlur}
        name={field.name}
      />
    );
  }

  return (
    <DataCell
      {...controlProps}
      kind="text"
      active
      value={field.value == null ? null : value}
      draftValue={value}
      className={compactJsonFormDataCellClass}
      onDraftValueChange={(nextValue) =>
        field.onChange(nextValue === "" && nullable ? null : nextValue)
      }
      onCommit={(nextValue) =>
        field.onChange(nextValue === "" && nullable ? null : nextValue)
      }
      onBlur={field.onBlur}
      name={field.name}
    />
  );
}

function shouldRenderTextarea(
  schema: Schema,
  textInput: JsonFormTextInput | undefined,
): boolean {
  if (textInput === "input") return false;
  if (textInput === "textarea") return true;
  return schema.format === "textarea" || (schema.maxLength ?? 0) > 120;
}

export function dataCellTextValue(value: unknown): string | null {
  return value === null || value === undefined ? null : String(value);
}

import type * as React from "react";

export type JsonFormTextInput = "input" | "textarea";
export type DateTimeControlKind = "date" | "time" | "date-time";

export interface ControlFieldApi {
  value: unknown;
  onChange: (value: unknown) => void;
  onBlur: () => void;
  name: string;
  ref?: React.Ref<HTMLElement>;
}

export type ScalarControlDomProps = {
  id?: string;
  "aria-describedby"?: string;
  "aria-invalid"?: boolean;
  "data-slot"?: string;
};

export const compactJsonFormDataCellClass =
  "h-8 rounded-md border-transparent bg-transparent px-2 text-sm shadow-none transition-colors hover:border-border hover:bg-background focus-visible:border-ring focus-visible:bg-background focus-visible:ring-1 focus-visible:ring-ring/30";

export const compactJsonFormSelectDataCellClass =
  "h-8 rounded-md border-transparent bg-transparent px-2 text-sm shadow-none transition-colors hover:border-border hover:bg-background focus-visible:border-ring focus-visible:bg-background focus-visible:ring-1 focus-visible:ring-ring/30";

import type { JSONSchema7, JSONSchema7Definition } from "json-schema";

export type Schema = JSONSchema7;
export type JsonFormSchemaNode = Schema;

export type FieldKind =
  | "string"
  | "number"
  | "integer"
  | "boolean"
  | "enum"
  | "object"
  | "array";

export type JsonFormFieldKind = FieldKind;

export interface NormalizedSchema {
  schema: Schema;
  nullable: boolean;
}

export interface Column {
  key: string;
  schema: Schema;
  kind: FieldKind;
  required: boolean;
  nullable: boolean;
}

export type JsonFormColumn = Column;

export function isSchema(
  value: JSONSchema7Definition | unknown,
): value is Schema {
  return typeof value === "object" && value !== null;
}

export function isRecordValue(
  value: unknown,
): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function cloneSchema(schema: Schema): Schema {
  return JSON.parse(JSON.stringify(schema)) as Schema;
}

function definitionsFrom(
  schema: Schema,
): Record<string, JSONSchema7Definition> {
  return {
    ...((schema.definitions ?? {}) as Record<string, JSONSchema7Definition>),
    ...((schema.$defs ?? {}) as Record<string, JSONSchema7Definition>),
  };
}

function mergeSchemas(base: Schema, next: Schema): Schema {
  const merged: Schema = { ...base, ...next };
  if (base.properties || next.properties) {
    const baseProperties = (base.properties ?? {}) as Record<
      string,
      JSONSchema7Definition
    >;
    const nextProperties = (next.properties ?? {}) as Record<
      string,
      JSONSchema7Definition
    >;
    merged.properties = { ...baseProperties };
    for (const [key, value] of Object.entries(nextProperties)) {
      const existing = merged.properties[key];
      merged.properties[key] =
        isSchema(existing) && isSchema(value)
          ? mergeSchemas(existing, value)
          : value;
    }
  }
  if (base.required || next.required) {
    merged.required = Array.from(
      new Set([...(base.required ?? []), ...(next.required ?? [])]),
    );
  }
  return merged;
}

function decodePointerSegment(segment: string): string {
  return segment.replace(/~1/g, "/").replace(/~0/g, "~");
}

function resolveLocalPointer(
  schema: Schema,
  ref: string,
): JSONSchema7Definition | undefined {
  if (!ref.startsWith("#/")) return undefined;

  let current: unknown = schema;
  for (const segment of ref.slice(2).split("/").map(decodePointerSegment)) {
    if (!isSchema(current) && !Array.isArray(current)) return undefined;
    current = (current as Record<string, unknown>)[segment];
  }
  return current as JSONSchema7Definition | undefined;
}

function refKey(ref: string): string | null {
  if (ref.startsWith("#/$defs/")) {
    return decodePointerSegment(ref.slice("#/$defs/".length));
  }
  if (ref.startsWith("#/definitions/")) {
    return decodePointerSegment(ref.slice("#/definitions/".length));
  }
  return null;
}

function resolveRef(
  ref: string,
  rootSchema: Schema,
  definitions: Record<string, JSONSchema7Definition>,
): JSONSchema7Definition | undefined {
  return resolveLocalPointer(rootSchema, ref) ?? definitions[refKey(ref) ?? ""];
}

export function normalizeJsonFormSchema(schema: Schema): JsonFormSchemaNode {
  return expandRefs(schema);
}

export function expandRefs(
  schema: Schema,
  definitions: Record<string, JSONSchema7Definition> = definitionsFrom(schema),
  visited: Set<string> = new Set(),
  rootSchema: Schema = schema,
): Schema {
  const working = cloneSchema(schema);

  if (typeof working.$ref === "string") {
    const ref = working.$ref;
    const target = resolveRef(ref, rootSchema, definitions);
    if (!isSchema(target) || visited.has(ref)) return working;

    const nextVisited = new Set(visited);
    nextVisited.add(ref);
    const { $ref: _ref, ...overrides } = working;
    return expandRefs(
      mergeSchemas(
        expandRefs(target, definitions, nextVisited, rootSchema),
        overrides,
      ),
      definitions,
      nextVisited,
      rootSchema,
    );
  }

  let normalized = working;
  if (Array.isArray(normalized.allOf)) {
    const allOf = normalized.allOf;
    delete normalized.allOf;
    normalized = allOf.reduce<Schema>((merged, branch) => {
      return isSchema(branch)
        ? mergeSchemas(
            merged,
            expandRefs(branch, definitions, visited, rootSchema),
          )
        : merged;
    }, normalized);
  }

  for (const key of ["anyOf", "oneOf"] as const) {
    const branches = normalized[key];
    if (Array.isArray(branches)) {
      normalized[key] = branches.map((branch) =>
        isSchema(branch)
          ? expandRefs(branch, definitions, visited, rootSchema)
          : branch,
      );
    }
  }

  if (normalized.properties) {
    const properties: Record<string, JSONSchema7Definition> = {};
    for (const [key, value] of Object.entries(normalized.properties)) {
      properties[key] = isSchema(value)
        ? expandRefs(value, definitions, visited, rootSchema)
        : value;
    }
    normalized.properties = properties;
  }

  if (isSchema(normalized.items)) {
    normalized.items = expandRefs(
      normalized.items,
      definitions,
      visited,
      rootSchema,
    );
  } else if (Array.isArray(normalized.items)) {
    normalized.items = normalized.items.map((item) =>
      isSchema(item)
        ? expandRefs(item, definitions, visited, rootSchema)
        : item,
    );
  }

  if (isSchema(normalized.additionalProperties)) {
    normalized.additionalProperties = expandRefs(
      normalized.additionalProperties,
      definitions,
      visited,
      rootSchema,
    );
  }

  if (normalized.patternProperties) {
    const patternProperties: Record<string, JSONSchema7Definition> = {};
    for (const [key, value] of Object.entries(normalized.patternProperties)) {
      patternProperties[key] = isSchema(value)
        ? expandRefs(value, definitions, visited, rootSchema)
        : value;
    }
    normalized.patternProperties = patternProperties;
  }

  return normalized;
}

/** Resolve nullable unions like `["string","null"]` or `anyOf:[X,{type:"null"}]`. */
export function unwrapNullable(schema: Schema): NormalizedSchema {
  if (Array.isArray(schema.type)) {
    const nonNull = schema.type.filter((type) => type !== "null");
    return {
      schema: {
        ...schema,
        type: nonNull.length === 1 ? nonNull[0] : nonNull,
      },
      nullable: schema.type.includes("null"),
    };
  }

  for (const key of ["anyOf", "oneOf"] as const) {
    const branches = schema[key];
    if (!Array.isArray(branches)) continue;

    const schemaBranches = branches.filter(isSchema);
    const nullable = schemaBranches.some((branch) => branch.type === "null");
    const main = schemaBranches.find((branch) => branch.type !== "null");
    if (main) {
      return {
        schema: {
          ...main,
          title: schema.title ?? main.title,
          description: schema.description ?? main.description,
        },
        nullable,
      };
    }
  }

  return { schema, nullable: false };
}

export function fieldKind(schema: Schema): FieldKind {
  if (Array.isArray(schema.enum)) return "enum";
  const type = Array.isArray(schema.type)
    ? schema.type.find((item) => item !== "null")
    : schema.type;
  switch (type) {
    case "number":
      return "number";
    case "integer":
      return "integer";
    case "boolean":
      return "boolean";
    case "object":
      return "object";
    case "array":
      return "array";
    default:
      return "string";
  }
}

export const jsonFormFieldKind = fieldKind;

export function labelFor(
  name: string,
  schema: Schema,
  explicit?: string,
): string {
  if (explicit) return explicit;
  if (schema.title) return schema.title;
  const leaf = name.split(".").pop() ?? name;
  return leaf
    .replace(/[_-]+/g, " ")
    .replace(/\b\w/g, (char) => char.toUpperCase())
    .trim();
}

export function emptyValueFor(schema: Schema): unknown {
  const { schema: inner, nullable } = unwrapNullable(schema);
  if (nullable) return null;
  switch (fieldKind(inner)) {
    case "boolean":
      return false;
    case "object":
      return {};
    case "array":
      return [];
    case "number":
    case "integer":
      return undefined;
    default:
      return "";
  }
}

export const emptyJsonFormValue = emptyValueFor;

export function isScalarKind(kind: FieldKind): boolean {
  return kind !== "object" && kind !== "array";
}

export function schemaProperties(
  schema: Schema,
): Record<string, JSONSchema7Definition> {
  return (schema.properties ?? {}) as Record<string, JSONSchema7Definition>;
}

export function schemaPatternProperties(
  schema: Schema,
): Record<string, JSONSchema7Definition> {
  return (schema.patternProperties ?? {}) as Record<
    string,
    JSONSchema7Definition
  >;
}

function patternPropertySchemaFor(schema: Schema, key: string): Schema | null {
  for (const [pattern, child] of Object.entries(
    schemaPatternProperties(schema),
  )) {
    if (!isRecordValue(child)) continue;
    try {
      if (new RegExp(pattern).test(key)) return child as Schema;
    } catch {
      continue;
    }
  }
  return null;
}

function additionalPropertySchemaFor(schema: Schema): Schema | null {
  return isRecordValue(schema.additionalProperties)
    ? (schema.additionalProperties as Schema)
    : null;
}

export function dynamicPropertySchemaFor(
  schema: Schema,
  key: string,
): Schema | null {
  return (
    patternPropertySchemaFor(schema, key) ?? additionalPropertySchemaFor(schema)
  );
}

export function hasDynamicObjectProperties(schema: Schema): boolean {
  const { schema: inner } = unwrapNullable(schema);
  if (fieldKind(inner) !== "object") return false;
  return (
    isRecordValue(inner.additionalProperties) ||
    Object.values(schemaPatternProperties(inner)).some(isRecordValue)
  );
}

export function scalarObjectColumns(itemSchema: Schema): Column[] | null {
  const { schema } = unwrapNullable(itemSchema);
  if (fieldKind(schema) !== "object") return null;
  const properties = schemaProperties(schema);
  const required = new Set(schema.required ?? []);
  const columns: Column[] = [];
  for (const [key, child] of Object.entries(properties)) {
    if (!isSchema(child)) return null;
    const { schema: inner, nullable } = unwrapNullable(child);
    const kind = fieldKind(inner);
    if (!isScalarKind(kind)) return null;
    columns.push({
      key,
      schema: inner,
      kind,
      required: required.has(key),
      nullable,
    });
  }
  return columns.length > 0 ? columns : null;
}

export function jsonFormTableColumns(itemSchema: Schema): Column[] | null {
  return scalarObjectColumns(itemSchema);
}

export function arrayItemSchemaAt(schema: Schema, index: number): Schema {
  const items = schema.items;
  if (Array.isArray(items)) {
    const item = items[index];
    if (isRecordValue(item)) return item as Schema;
    if (isRecordValue(schema.additionalItems)) {
      return schema.additionalItems as Schema;
    }
    return { type: "string" };
  }
  return isRecordValue(items) ? (items as Schema) : { type: "string" };
}

export const jsonFormArrayItemNode = arrayItemSchemaAt;

export function canAppendArrayItem(schema: Schema, length: number): boolean {
  if (typeof schema.maxItems === "number" && length >= schema.maxItems) {
    return false;
  }
  if (
    Array.isArray(schema.items) &&
    schema.additionalItems === false &&
    length >= schema.items.length
  ) {
    return false;
  }
  return true;
}

export function canRemoveArrayItem(schema: Schema, length: number): boolean {
  return typeof schema.minItems !== "number" || length > schema.minItems;
}

"use client";

import * as React from "react";

import type { SourceFieldLink } from "@/components/ui/source-field-link";
import { useSourceLinkFocusPreviewIntent } from "@/components/json-form/source-link-focus-intent";
import { useKeyedMountEffect } from "@/hooks/use-keyed-mount-effect";
import { joinEffectKey } from "@/lib/effect-key";

export type JsonFormSourceLinkActions = Omit<
  SourceFieldLink,
  "activeSourcePath"
>;

type SourceTableCell = HTMLElement;
type SourcePointerPoint = { x: number; y: number };
type TableSourceHoverState = {
  phase: "idle" | "focusing" | "hovering" | "scrolling";
  pointerPoint: SourcePointerPoint | null;
  sourcePath: string | null;
};

const SOURCE_PATH_ATTRIBUTE = "data-source-path";
const SOURCE_ACTIVE_ATTRIBUTE = "data-source-active";
const SOURCE_CELL_SELECTOR = `[${SOURCE_PATH_ATTRIBUTE}]`;
const TABLE_CELL_SELECTOR = "[data-table-cell]";
const SCROLL_SOURCE_HOVER_INTERVAL_MS = 32;

export function useSourceTableHoverController({
  tableRef,
  activeSourcePath,
  sourceLinkActions,
  refreshKey,
}: {
  tableRef: React.RefObject<HTMLElement | null>;
  activeSourcePath: string | null;
  sourceLinkActions: JsonFormSourceLinkActions | null;
  refreshKey: unknown;
}) {
  const sourceLinked = Boolean(sourceLinkActions);
  const activeSourceCellRef = React.useRef<Element | null>(null);
  const hoverStateRef = React.useRef<TableSourceHoverState>({
    phase: "idle",
    pointerPoint: null,
    sourcePath: null,
  });
  const pendingHoverPathRef = React.useRef<string | null>(null);
  const pendingHoverFrameRef = React.useRef<number | null>(null);
  const pendingScrollHoverFrameRef = React.useRef<number | null>(null);
  const latestScrollHoverAtRef = React.useRef(Number.NEGATIVE_INFINITY);
  const shouldPreviewFocus = useSourceLinkFocusPreviewIntent();

  const setActiveSourceCell = React.useCallback((cell: Element | null) => {
    if (activeSourceCellRef.current === cell) return;
    activeSourceCellRef.current?.removeAttribute(SOURCE_ACTIVE_ATTRIBUTE);
    if (cell) cell.setAttribute(SOURCE_ACTIVE_ATTRIBUTE, "true");
    activeSourceCellRef.current = cell;
  }, []);

  const sourcePathForCell = React.useCallback(
    (cell: Element | null): string | null =>
      cell?.getAttribute(SOURCE_PATH_ATTRIBUTE) ?? null,
    [],
  );

  useKeyedMountEffect(
    joinEffectKey([
      activeSourcePath,
      sourceLinked,
      refreshKey,
      setActiveSourceCell,
      tableRef,
    ]),
    () => {
      if (!sourceLinked || !activeSourcePath) {
        setActiveSourceCell(null);
        return;
      }
      if (
        hoverStateRef.current.sourcePath === activeSourcePath &&
        activeSourceCellRef.current?.getAttribute(SOURCE_PATH_ATTRIBUTE) ===
          activeSourcePath
      ) {
        return;
      }

      const table = tableRef.current;
      if (!table) return;
      for (const cell of table.querySelectorAll(SOURCE_CELL_SELECTOR)) {
        if (cell.getAttribute(SOURCE_PATH_ATTRIBUTE) === activeSourcePath) {
          setActiveSourceCell(cell);
          return;
        }
      }
      setActiveSourceCell(null);
    },
  );

  const getCellFromTarget = React.useCallback(
    (target: EventTarget | null): SourceTableCell | null => {
      if (!(target instanceof Element)) return null;
      const cell = target.closest<SourceTableCell>(TABLE_CELL_SELECTOR);
      return cell && tableRef.current?.contains(cell) ? cell : null;
    },
    [tableRef],
  );

  const cancelPendingHover = React.useCallback(() => {
    if (pendingHoverFrameRef.current === null) return;
    cancelAnimationFrame(pendingHoverFrameRef.current);
    pendingHoverFrameRef.current = null;
  }, []);

  const cancelPendingScrollHover = React.useCallback(() => {
    if (pendingScrollHoverFrameRef.current === null) return;
    cancelAnimationFrame(pendingScrollHoverFrameRef.current);
    pendingScrollHoverFrameRef.current = null;
  }, []);

  const reportHoverSourcePath = React.useCallback(
    (path: string | null) => {
      if (!sourceLinkActions) return;
      pendingHoverPathRef.current = path;
      if (pendingHoverFrameRef.current !== null) return;
      pendingHoverFrameRef.current = requestAnimationFrame(() => {
        pendingHoverFrameRef.current = null;
        sourceLinkActions.onSourceHover(pendingHoverPathRef.current);
      });
    },
    [sourceLinkActions],
  );

  const setHoverSourcePath = React.useCallback(
    (path: string | null, cell: Element | null) => {
      if (!sourceLinkActions) return;
      const currentState = hoverStateRef.current;
      if (currentState.sourcePath === path) return;
      hoverStateRef.current = {
        phase:
          currentState.phase === "scrolling"
            ? "scrolling"
            : path
              ? "hovering"
              : "idle",
        pointerPoint: currentState.pointerPoint,
        sourcePath: path,
      };
      setActiveSourceCell(cell);
      reportHoverSourcePath(path);
    },
    [sourceLinkActions, reportHoverSourcePath, setActiveSourceCell],
  );

  useKeyedMountEffect(
    joinEffectKey([cancelPendingHover, cancelPendingScrollHover]),
    () => () => {
      cancelPendingHover();
      cancelPendingScrollHover();
    },
  );

  const selectCellSource = React.useCallback(
    (cell: HTMLElement | null) => {
      const sourcePath = sourcePathForCell(cell);
      if (!sourcePath) return false;
      cancelPendingHover();
      sourceLinkActions?.selectSourcePath?.(sourcePath);
      return true;
    },
    [cancelPendingHover, sourceLinkActions, sourcePathForCell],
  );

  const handlePointerMove = React.useCallback(
    (event: React.PointerEvent<HTMLElement>) => {
      if (!sourceLinkActions) return;
      hoverStateRef.current = {
        ...hoverStateRef.current,
        pointerPoint: {
          x: event.clientX,
          y: event.clientY,
        },
      };
      if (hoverStateRef.current.phase === "scrolling") return;
      const cell = getCellFromTarget(event.target);
      setHoverSourcePath(sourcePathForCell(cell), cell);
    },
    [
      sourceLinkActions,
      getCellFromTarget,
      setHoverSourcePath,
      sourcePathForCell,
    ],
  );

  const handlePointerLeave = React.useCallback(
    (event: React.PointerEvent<HTMLElement>) => {
      hoverStateRef.current = {
        ...hoverStateRef.current,
        pointerPoint: {
          x: event.clientX,
          y: event.clientY,
        },
      };
      setHoverSourcePath(null, null);
    },
    [setHoverSourcePath],
  );

  const handleScrollStart = React.useCallback(() => {
    hoverStateRef.current = {
      phase: "scrolling",
      pointerPoint: hoverStateRef.current.pointerPoint,
      sourcePath: hoverStateRef.current.sourcePath,
    };
  }, []);

  const restoreHoverSourceAtPointer = React.useCallback(() => {
    if (!sourceLinkActions) return;
    const point = hoverStateRef.current.pointerPoint;
    if (!point) return;
    const ownerDocument = tableRef.current?.ownerDocument;
    if (!ownerDocument) return;
    const element = ownerDocument.elementFromPoint(point.x, point.y);
    const cell = getCellFromTarget(element);
    setHoverSourcePath(sourcePathForCell(cell), cell);
  }, [
    sourceLinkActions,
    tableRef,
    getCellFromTarget,
    setHoverSourcePath,
    sourcePathForCell,
  ]);

  const handleScrollEnd = React.useCallback(() => {
    hoverStateRef.current = {
      phase: hoverStateRef.current.sourcePath ? "hovering" : "idle",
      pointerPoint: hoverStateRef.current.pointerPoint,
      sourcePath: hoverStateRef.current.sourcePath,
    };
    cancelPendingScrollHover();
    latestScrollHoverAtRef.current = Number.NEGATIVE_INFINITY;
    restoreHoverSourceAtPointer();
  }, [cancelPendingScrollHover, restoreHoverSourceAtPointer]);

  const handleScrollMove = React.useCallback(() => {
    if (!sourceLinkActions || pendingScrollHoverFrameRef.current !== null) {
      return;
    }
    const now = performance.now();
    if (
      now - latestScrollHoverAtRef.current <
      SCROLL_SOURCE_HOVER_INTERVAL_MS
    ) {
      return;
    }
    pendingScrollHoverFrameRef.current = requestAnimationFrame(() => {
      pendingScrollHoverFrameRef.current = null;
      latestScrollHoverAtRef.current = performance.now();
      restoreHoverSourceAtPointer();
    });
  }, [sourceLinkActions, restoreHoverSourceAtPointer]);

  const handleFocus = React.useCallback(
    (event: React.FocusEvent<HTMLElement>) => {
      if (!sourceLinkActions) return;
      if (!shouldPreviewFocus(event)) return;
      const cell = getCellFromTarget(event.target);
      if (!cell) return;
      const sourcePath = sourcePathForCell(cell);
      hoverStateRef.current = {
        phase: sourcePath ? "focusing" : "idle",
        pointerPoint: hoverStateRef.current.pointerPoint,
        sourcePath,
      };
      setActiveSourceCell(cell);
      sourceLinkActions.onSourceHover(sourcePath);
    },
    [
      sourceLinkActions,
      shouldPreviewFocus,
      getCellFromTarget,
      setActiveSourceCell,
      sourcePathForCell,
    ],
  );

  const handleBlur = React.useCallback(
    (event: React.FocusEvent<HTMLElement>) => {
      if (!sourceLinkActions) return;
      const cell = getCellFromTarget(event.target);
      if (!cell || cell.contains(event.relatedTarget as Node | null)) return;
      const sourcePath = sourcePathForCell(cell);
      if (
        hoverStateRef.current.phase !== "focusing" ||
        hoverStateRef.current.sourcePath !== sourcePath
      ) {
        return;
      }
      hoverStateRef.current = {
        phase: "idle",
        pointerPoint: hoverStateRef.current.pointerPoint,
        sourcePath: null,
      };
      setActiveSourceCell(null);
      sourceLinkActions.onSourceHover(null);
    },
    [
      sourceLinkActions,
      getCellFromTarget,
      setActiveSourceCell,
      sourcePathForCell,
    ],
  );

  return {
    sourceLinked,
    getCellFromTarget,
    selectCellSource,
    handlePointerMove,
    handlePointerLeave,
    handleFocus,
    handleBlur,
    handleScrollStart,
    handleScrollMove,
    handleScrollEnd,
  };
}

"use client";

import * as React from "react";

import { cn } from "@/lib/utils";
import type { SourceFieldLink } from "@/components/ui/source-field-link";
import { useSourceLinkFocusPreviewIntent } from "@/components/json-form/source-link-focus-intent";
import {
  useSourceTableHoverController,
  type JsonFormSourceLinkActions,
} from "@/components/json-form/source-link-table-hover";

export type JsonFormSourceLink = SourceFieldLink;

const ActiveSourcePathContext = React.createContext<string | null>(null);
const SourceLinkActionsContext =
  React.createContext<JsonFormSourceLinkActions | null>(null);

export function JsonFormSourceLinkProvider({
  sourceLink,
  children,
}: {
  sourceLink?: JsonFormSourceLink;
  children: React.ReactNode;
}) {
  const onSourceHover = sourceLink?.onSourceHover;
  const selectSourcePath = sourceLink?.selectSourcePath;
  const sourceLinkActions = React.useMemo<JsonFormSourceLinkActions | null>(
    () => (onSourceHover ? { onSourceHover, selectSourcePath } : null),
    [onSourceHover, selectSourcePath],
  );

  return (
    <SourceLinkActionsContext.Provider value={sourceLinkActions}>
      <ActiveSourcePathContext.Provider
        value={sourceLink?.activeSourcePath ?? null}
      >
        {children}
      </ActiveSourcePathContext.Provider>
    </SourceLinkActionsContext.Provider>
  );
}

export function useActiveSourcePath(): string | null {
  return React.useContext(ActiveSourcePathContext);
}

export function useSourceLinkActions(): JsonFormSourceLinkActions | null {
  return React.useContext(SourceLinkActionsContext);
}

export function useSourceLinkedTableCells({
  tableRef,
  refreshKey,
}: {
  tableRef: React.RefObject<HTMLElement | null>;
  refreshKey: unknown;
}) {
  return useSourceTableHoverController({
    activeSourcePath: useActiveSourcePath(),
    refreshKey,
    sourceLinkActions: useSourceLinkActions(),
    tableRef,
  });
}

function shouldSelectSourceFromKeyDown(event: React.KeyboardEvent): boolean {
  if (event.defaultPrevented || event.key !== "Enter") return false;
  return !(event.target instanceof HTMLTextAreaElement);
}

function shouldPreviewSourceFromPointerMove(
  event: React.PointerEvent,
): boolean {
  return !event.defaultPrevented && event.pointerType !== "touch";
}

/**
 * Wraps a scalar leaf so it reports its source path from explicit pointer or
 * keyboard intent. Without a source link, it renders children unchanged.
 */
export function SourceLinkShell({
  sourcePath,
  children,
}: {
  sourcePath: string;
  children: React.ReactNode;
}) {
  const activeSourcePath = useActiveSourcePath();
  const sourceLinkActions = useSourceLinkActions();
  const shouldPreviewFocus = useSourceLinkFocusPreviewIntent();
  const focusPreviewedRef = React.useRef(false);
  const pointerPreviewedRef = React.useRef(false);
  if (!sourceLinkActions) return <>{children}</>;
  const active = activeSourcePath === sourcePath;

  const clearPreviewIfIdle = () => {
    if (focusPreviewedRef.current || pointerPreviewedRef.current) return;
    sourceLinkActions.onSourceHover(null);
  };

  return (
    <div
      data-source-active={active ? "true" : "false"}
      data-source-path={sourcePath}
      onPointerMove={(event) => {
        if (
          pointerPreviewedRef.current ||
          !shouldPreviewSourceFromPointerMove(event)
        ) {
          return;
        }
        pointerPreviewedRef.current = true;
        sourceLinkActions.onSourceHover(sourcePath);
      }}
      onPointerLeave={() => {
        if (!pointerPreviewedRef.current) return;
        pointerPreviewedRef.current = false;
        clearPreviewIfIdle();
      }}
      onFocus={(event) => {
        if (!shouldPreviewFocus(event)) return;
        focusPreviewedRef.current = true;
        sourceLinkActions.onSourceHover(sourcePath);
      }}
      onBlur={() => {
        if (!focusPreviewedRef.current) return;
        focusPreviewedRef.current = false;
        clearPreviewIfIdle();
      }}
      onClick={() => sourceLinkActions.selectSourcePath?.(sourcePath)}
      onKeyDownCapture={(event) => {
        if (shouldSelectSourceFromKeyDown(event)) {
          sourceLinkActions.selectSourcePath?.(sourcePath);
        }
      }}
      className={cn(
        "rounded-md border px-3 py-2 transition-colors",
        active
          ? "border-primary/40 bg-primary/5"
          : "hover:bg-muted/60 border-transparent",
      )}
    >
      {children}
    </div>
  );
}

