export function StaticArrayTableBody({
  fields,
  scrollHandlers,
  renderItem,
}: {
  fields: ArrayTableField[];
  scrollHandlers: ArrayTableScrollHandlers;
  renderItem: (index: number) => React.ReactNode;
}) {
