  const { virtualRowWindow, totalRowSize, viewportClientHeight } =
    useFixedRowVirtualization({
      rowCount: fields.length,
      rowSize: TABLE_ROW_HEIGHT,
      rowOverscan: TABLE_ROW_OVERSCAN,
