    !isEditing
      ? "hover:bg-background focus-visible:bg-background focus-visible:ring-1 focus-visible:ring-ring/30"
      : "px-1 py-0.5",
    model.sourceLinked && isEditing && "hover:bg-muted/55",
  );
}

export function arrayTableCellProps(
