import * as React from "react";
import { X } from "lucide-react";
import { useFormContext, useWatch } from "react-hook-form";

import { cn } from "@/lib/utils";
import { getFixedGridRowStyle } from "@/components/ui/fixed-grid-row-style";
import {
  encodeJsonFormKey,
  joinJsonFormPath,
  joinJsonSourcePath,
} from "@/components/json-form/path-codec";
import type { Column } from "@/components/json-form/schema-model";
import type { ArrayTableActiveCellStore } from "@/components/json-form/table/array-table-active-cell-store";
import { ArrayTableCell } from "@/components/json-form/table/array-table-cell";
import { createArrayTableCellModel } from "@/components/json-form/table/array-table-cell-model";
import { TABLE_ROW_HEIGHT } from "@/components/json-form/table/array-table-config";

export const ArrayTableRow = React.memo(function ArrayTableRow({
  name,
  sourcePath,
  index,
  isLastRow,
  columns,
  remove,
  canRemove,
  sourceLinked,
  template,
  rowTopPx,
  activeCellStore,
}: {
  name: string;
  sourcePath: string;
  index: number;
  isLastRow: boolean;
  columns: Column[];
  remove: (index: number) => void;
  canRemove: boolean;
  sourceLinked: boolean;
  template: string;
  rowTopPx?: number;
  activeCellStore: ArrayTableActiveCellStore;
}) {
  const { control, getValues, setValue } = useFormContext();
  const rowPath = joinJsonFormPath(name, index);
  const rowSourcePath = joinJsonSourcePath(sourcePath, index);
  const watchedRowValue = useWatch({
    control,
    name: rowPath,
  }) as Record<string, unknown> | undefined;
  const rowValue = (watchedRowValue ?? getValues(rowPath)) as
    | Record<string, unknown>
    | undefined;
  const rowStyle = React.useMemo(
    () =>
      rowTopPx === undefined
        ? { gridTemplateColumns: template }
        : getFixedGridRowStyle({
            gridTemplate: template,
            rowHeight: TABLE_ROW_HEIGHT,
            top: rowTopPx,
          }),
    [rowTopPx, template],
  );
  const closeEditor = React.useCallback(
    () => activeCellStore.setActivePath(null),
    [activeCellStore],
  );

  return (
    <div
      data-index={index}
      className={cn(
        "hover:bg-muted/25 grid items-center gap-1 border-b px-2 py-1 [contain:layout_paint_style]",
        isLastRow && "border-b-0",
      )}
      style={rowStyle}
    >
      {columns.map((column) => {
        const path = joinJsonFormPath(rowPath, column.key);
        const value = rowValue?.[encodeJsonFormKey(column.key)];

        return (
          <ArrayTableCell
            key={column.key}
            model={createArrayTableCellModel({
              path,
              sourcePath: joinJsonSourcePath(rowSourcePath, column.key),
              column,
              value,
              sourceLinked,
            })}
            column={column}
            activeCellStore={activeCellStore}
            setValue={setValue}
            closeEditor={closeEditor}
          />
        );
      })}
      <button
        type="button"
        className="text-muted-foreground hover:border-border hover:text-destructive focus-visible:ring-ring flex size-8 items-center justify-center rounded-md border border-transparent text-base leading-none transition-colors focus-visible:ring-2 focus-visible:outline-none disabled:pointer-events-none disabled:opacity-50"
        onClick={() => remove(index)}
        aria-label="Remove row"
        disabled={!canRemove}
      >
        <X className="size-4" />
      </button>
    </div>
  );
});

"use client";

import * as React from "react";

import { useMountEffect } from "@/hooks/use-mount-effect";

export type ArrayTableScrollHandlers = {
  onScrollStart: () => void;
  onScrollMove: () => void;
  onScrollEnd: () => void;
};

export function useArrayTableScrollActivity(
  scrollRef: React.RefObject<HTMLElement | null>,
  { onScrollStart, onScrollMove, onScrollEnd }: ArrayTableScrollHandlers,
) {
  const isScrollingRef = React.useRef(false);
  const scrollEndTimeoutRef = React.useRef(0);
  const callbacksRef = React.useRef({
    onScrollStart,
    onScrollMove,
    onScrollEnd,
  });
  callbacksRef.current = { onScrollStart, onScrollMove, onScrollEnd };

  const handleScroll = React.useCallback(() => {
    if (!isScrollingRef.current) {
      isScrollingRef.current = true;
      callbacksRef.current.onScrollStart();
    }
    callbacksRef.current.onScrollMove();
    window.clearTimeout(scrollEndTimeoutRef.current);
    scrollEndTimeoutRef.current = window.setTimeout(() => {
      isScrollingRef.current = false;
      callbacksRef.current.onScrollEnd();
    }, 120);
  }, []);

  useMountEffect(() => {
    const scrollElement = scrollRef.current;
    if (!scrollElement) return;
    scrollElement.addEventListener("scroll", handleScroll, { passive: true });
    return () => {
      window.clearTimeout(scrollEndTimeoutRef.current);
      scrollElement.removeEventListener("scroll", handleScroll);
    };
  });
}

"use client";

import * as React from "react";

import { getFixedGridCanvasStyle } from "@/components/ui/fixed-grid-layout";
import { WithDescription } from "@/components/json-form/disclosure";
import { labelFor, type Column } from "@/components/json-form/schema-model";
import { useSourceLinkedTableCells } from "@/components/json-form/source-link";
import {
  createArrayTableActiveCellStore,
  type ArrayTableActiveCellStore,
} from "@/components/json-form/table/array-table-active-cell-store";
import {
  FixedArrayTableBody,
  StaticArrayTableBody,
} from "@/components/json-form/table/array-table-body";
import {
  TABLE_SCROLL_THRESHOLD,
  TABLE_VIRTUALIZE_THRESHOLD,
} from "@/components/json-form/table/array-table-config";
import { ArrayTableRow } from "@/components/json-form/table/array-table-row";

export function ArrayTable({
  name,
  sourcePath,
  fields,
  remove,
  canRemove,
  columns,
}: {
  name: string;
  sourcePath: string;
  fields: { id: string }[];
  remove: (index: number) => void;
  canRemove: boolean;
  columns: Column[];
}) {
  const template = `${columns.map(() => "minmax(9rem, 1fr)").join(" ")} 2.25rem`;
  const minWidth = columns.length * 150 + 36;
  const activeCellStoreRef = React.useRef<ArrayTableActiveCellStore | null>(null);
  if (!activeCellStoreRef.current) {
    activeCellStoreRef.current = createArrayTableActiveCellStore();
  }
  const activeCellStore = activeCellStoreRef.current;
  const tableRef = React.useRef<HTMLDivElement>(null);
  const sourceTable = useSourceLinkedTableCells({
    tableRef,
    refreshKey: fields.length,
  });
  const sourceLinked = sourceTable.sourceLinked;
  const virtualize = fields.length > TABLE_VIRTUALIZE_THRESHOLD;
  const scrollHandlers = React.useMemo(
    () => ({
      onScrollStart: sourceTable.handleScrollStart,
      onScrollMove: sourceTable.handleScrollMove,
      onScrollEnd: sourceTable.handleScrollEnd,
    }),
    [sourceTable],
  );

  const handleTableClickCapture = React.useCallback(
    (event: React.MouseEvent<HTMLDivElement>) => {
      const table = tableRef.current;
      const activeElement = table?.ownerDocument.activeElement;
      if (
        !(activeElement instanceof HTMLElement) ||
        activeElement.dataset.tableCellEditor !== "true" ||
        !table?.contains(activeElement) ||
        activeElement === event.target ||
        activeElement.contains(event.target as Node)
      ) {
        return;
      }
      activeElement.blur();
    },
    [],
  );

  const handleTableClick = React.useCallback(
    (event: React.MouseEvent<HTMLDivElement>) => {
      const cell = sourceTable.getCellFromTarget(event.target);
      if (!cell) return;
      sourceTable.selectCellSource(cell);
      if (cell.dataset.tableCellEditable !== "true") return;
      const path = cell.dataset.tableCellPath;
      if (path) activeCellStore.setActivePath(path);
    },
    [activeCellStore, sourceTable],
  );

  const handleTableKeyDown = React.useCallback(
    (event: React.KeyboardEvent<HTMLDivElement>) => {
      if (event.key !== "Enter" && event.key !== " ") return;
      const cell = sourceTable.getCellFromTarget(event.target);
      if (!cell || cell.dataset.tableCellEditable !== "true") return;
      const path = cell.dataset.tableCellPath;
      if (!path) return;
      sourceTable.selectCellSource(cell);
      event.preventDefault();
      activeCellStore.setActivePath(path);
    },
    [activeCellStore, sourceTable],
  );

  const renderRow = React.useCallback(
    (index: number, rowTopPx?: number) => (
      <ArrayTableRow
        name={name}
        sourcePath={sourcePath}
        index={index}
        isLastRow={index === fields.length - 1}
        columns={columns}
        remove={remove}
        canRemove={canRemove}
        sourceLinked={sourceLinked}
        template={template}
        rowTopPx={rowTopPx}
        activeCellStore={activeCellStore}
      />
    ),
    [
      activeCellStore,
      name,
      sourcePath,
      fields.length,
      columns,
      remove,
      canRemove,
      sourceLinked,
      template,
    ],
  );

  return (
    <div
      ref={tableRef}
      onClickCapture={handleTableClickCapture}
      onClick={handleTableClick}
      onKeyDown={handleTableKeyDown}
      onPointerMove={sourceLinked ? sourceTable.handlePointerMove : undefined}
      onPointerLeave={sourceLinked ? sourceTable.handlePointerLeave : undefined}
      onFocus={sourceTable.handleFocus}
      onBlur={sourceTable.handleBlur}
      className="bg-background overflow-x-auto"
    >
      <div style={getFixedGridCanvasStyle({ minWidth })}>
        <div
          className="bg-muted/35 grid h-9 items-center gap-1 border-b px-2"
          style={{ gridTemplateColumns: template }}
        >
          {columns.map((column) => (
            <div
              key={column.key}
              className="text-muted-foreground flex min-w-0 items-center gap-1 px-2 text-xs font-medium"
            >
              <WithDescription text={column.schema.description}>
                <span className="truncate">
                  {labelFor(column.key, column.schema)}
                </span>
              </WithDescription>
              {column.required ? (
                <span className="text-destructive">*</span>
              ) : null}
            </div>
          ))}
          <span className="sr-only">Actions</span>
        </div>
        {virtualize ? (
          <FixedArrayTableBody
            fields={fields}
            scrollHandlers={scrollHandlers}
            renderItem={renderRow}
          />
        ) : fields.length > TABLE_SCROLL_THRESHOLD ? (
          <StaticArrayTableBody
            fields={fields}
            scrollHandlers={scrollHandlers}
            renderItem={renderRow}
          />
        ) : (
          <div>
            {fields.map((entry, index) => (
              <React.Fragment key={entry.id}>{renderRow(index)}</React.Fragment>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import * as React from "react";

import { FixedGridRowWindow } from "@/components/ui/fixed-grid-row-window";
import { useMeasuredRowVirtualization } from "@/components/ui/measured-row-virtualization";

export function VirtualList({
  fields,
  estimateSize,
  renderItem,
  maxHeight = 480,
  gap = 0,
}: {
  fields: { id: string }[];
  estimateSize: number;
  renderItem: (index: number) => React.ReactNode;
  maxHeight?: number;
  gap?: number;
}) {
  const parentRef = React.useRef<HTMLDivElement>(null);
  const getItemKey = React.useCallback(
    (index: number) => fields[index]?.id ?? index,
    [fields],
  );
  const { measureRow, totalSize, viewportClientHeight, virtualRowWindow } =
    useMeasuredRowVirtualization({
      count: fields.length,
      estimateSize: estimateSize + gap,
      getItemKey,
      overscan: 8,
      scrollRef: parentRef,
    });

  return (
    <div ref={parentRef} style={{ maxHeight }} className="overflow-y-auto">
      <FixedGridRowWindow
        data-slot="json-form-virtual-list-spacer"
        totalSize={totalSize}
        virtualRowWindow={virtualRowWindow}
        viewportHeight={viewportClientHeight}
        offsetDataSlot="json-form-virtual-list-row-offset"
        windowDataSlot="json-form-virtual-list-row-window"
      >
        {virtualRowWindow.items.map((virtualRow) => (
          <div
            key={virtualRow.key}
            data-index={virtualRow.index}
            ref={(element) => measureRow(virtualRow.index, element)}
            style={{
              position: "absolute",
              top: 0,
              left: 0,
              width: "100%",
              transform: `translateY(${virtualRow.start}px)`,
              paddingBottom: gap,
            }}
          >
            {renderItem(virtualRow.index)}
          </div>
        ))}
      </FixedGridRowWindow>
    </div>
  );
}

"use client";

import * as React from "react";

import { useKeyedLayoutEffect } from "@/hooks/use-keyed-layout-effect";
import { joinEffectKey } from "@/lib/effect-key";

const DEFAULT_INITIAL_VIEWPORT_HEIGHT = 600;
const DEFAULT_OVERSCAN = 6;
const MAX_VIRTUAL_ITEMS = 1_000;

export interface MeasuredRowVirtualItem {
  index: number;
  key: React.Key;
  start: number;
  size: number;
  end: number;
}

export interface MeasuredRowVirtualItemWindow {
  end: number;
  items: MeasuredRowVirtualItem[];
  size: number;
  start: number;
}

export interface MeasuredRowOffsets {
  starts: number[];
  totalSize: number;
}

export interface MeasuredRowScrollTarget {
  align?: "start" | "center" | "end";
  behavior?: ScrollBehavior;
}

export function buildMeasuredRowOffsets({
  rowSizes,
  paddingStart = 0,
  paddingEnd = 0,
}: {
  rowSizes: readonly number[];
  paddingStart?: number;
  paddingEnd?: number;
}): MeasuredRowOffsets {
  const starts: number[] = [];
  let offset = safeSize(paddingStart);

  for (const rowSize of rowSizes) {
    starts.push(offset);
    offset += safeSize(rowSize);
  }

  return {
    starts,
    totalSize: offset + safeSize(paddingEnd),
  };
}

export function getMeasuredRowVirtualItems({
  getItemKey,
  maxItems = MAX_VIRTUAL_ITEMS,
  offsets,
  overscan = DEFAULT_OVERSCAN,
  rowSizes,
  scrollTop,
  viewportHeight,
}: {
  getItemKey?: (index: number) => React.Key;
  maxItems?: number;
  offsets: MeasuredRowOffsets;
  overscan?: number;
  rowSizes: readonly number[];
  scrollTop: number;
  viewportHeight: number;
}): MeasuredRowVirtualItem[] {
  const count = rowSizes.length;
  if (count === 0) return [];

  const safeScrollTop = safeOffset(scrollTop);
  const safeViewportHeight = Math.max(1, safeSize(viewportHeight));
  const visibleStartIndex = findFirstRowEndingAfter({
    offset: safeScrollTop,
    rowSizes,
    starts: offsets.starts,
  });
  const visibleEndExclusive = findFirstRowStartingAtOrAfter({
    offset: safeScrollTop + safeViewportHeight,
    starts: offsets.starts,
  });
  const start = Math.max(0, visibleStartIndex - safeCount(overscan));
  const end = Math.min(
    count,
    Math.max(visibleStartIndex + 1, visibleEndExclusive) + safeCount(overscan),
  );
  const [cappedStart, cappedEnd] = capMeasuredRowRange({
    count,
    end,
    maxItems,
    start,
    visibleEnd: Math.min(
      count,
      Math.max(visibleStartIndex + 1, visibleEndExclusive),
    ),
    visibleStart: visibleStartIndex,
  });

  return Array.from({ length: cappedEnd - cappedStart }, (_, offset) => {
    const index = cappedStart + offset;
    const rowStart = offsets.starts[index] ?? 0;
    const size = safeSize(rowSizes[index]);
    return {
      index,
      key: getItemKey?.(index) ?? index,
      start: rowStart,
      size,
      end: rowStart + size,
    };
  });
}

export function measuredRowVirtualItemWindow(
  items: readonly MeasuredRowVirtualItem[],
): MeasuredRowVirtualItemWindow {
  const start = items[0]?.start ?? 0;
  const end = items.length ? items[items.length - 1]!.end : start;

  return {
    end,
    items: items.map((item) => ({
      ...item,
      start: item.start - start,
      end: item.end - start,
    })),
    size: Math.max(0, end - start),
    start,
  };
}

export function measuredRowScrollTopForIndex({
  align = "center",
  index,
  offsets,
  rowSizes,
  viewportHeight,
}: {
  align?: NonNullable<MeasuredRowScrollTarget["align"]>;
  index: number;
  offsets: MeasuredRowOffsets;
  rowSizes: readonly number[];
  viewportHeight: number;
}) {
  if (!Number.isSafeInteger(index) || index < 0) return 0;

  const rowStart = offsets.starts[index];
  if (rowStart == null) return 0;

  const rowSize = safeSize(rowSizes[index]);
  const safeViewportHeight = safeSize(viewportHeight);

  if (align === "end")
    return Math.max(0, rowStart - safeViewportHeight + rowSize);
  if (align === "center") {
    return Math.max(0, rowStart - safeViewportHeight / 2 + rowSize / 2);
  }
  return Math.max(0, rowStart);
}

export function useMeasuredRowVirtualization({
  count,
  estimateSize,
  getItemKey,
  initialViewportHeight = DEFAULT_INITIAL_VIEWPORT_HEIGHT,
  overscan = DEFAULT_OVERSCAN,
  paddingEnd = 0,
  paddingStart = 0,
  scrollRef,
}: {
  count: number;
  estimateSize: number;
  getItemKey?: (index: number) => React.Key;
  initialViewportHeight?: number;
  overscan?: number;
  paddingEnd?: number;
  paddingStart?: number;
  scrollRef: React.RefObject<HTMLElement | null>;
}) {
  const safeCount = measuredRowCount(count);
  const safeEstimateSize = Math.max(1, safeSize(estimateSize));
  const [version, forceVersion] = React.useReducer(
    (current: number) => current + 1,
    0,
  );
  const [scrollElement, setScrollElement] = React.useState<HTMLElement | null>(
    scrollRef.current,
  );
  const [viewport, setViewport] = React.useState({
    clientHeight: 0,
    scrollTop: 0,
  });
  const measuredSizesRef = React.useRef(new Map<number, number>());
  const rowElementsRef = React.useRef(new Map<number, HTMLElement>());
  const observedIndexesRef = React.useRef(new Map<HTMLElement, number>());
  const rowObserverRef = React.useRef<ResizeObserver | null>(null);
  const offsetsRef = React.useRef<MeasuredRowOffsets>({
    starts: [],
    totalSize: 0,
  });
  const rowSizesRef = React.useRef<number[]>([]);
  const viewportRef = React.useRef(viewport);

  viewportRef.current = viewport;

  const updateMeasuredSize = React.useCallback(
    (index: number, nextSize: number | null) => {
      if (!Number.isSafeInteger(index) || index < 0 || index >= safeCount) {
        return;
      }
      if (nextSize == null) return;

      const safeNextSize = safeSize(nextSize);
      if (safeNextSize <= 0) return;

      const measuredSizes = measuredSizesRef.current;
      const previousSize = measuredSizes.get(index) ?? safeEstimateSize;
      if (previousSize === safeNextSize) return;

      const previousOffsets = offsetsRef.current;
      const previousStart = previousOffsets.starts[index] ?? 0;
      const previousEnd = previousStart + previousSize;
      const delta = safeNextSize - previousSize;
      const currentScrollTop = viewportRef.current.scrollTop;

      measuredSizes.set(index, safeNextSize);

      const currentScrollElement = scrollRef.current;
      if (
        currentScrollElement &&
        previousEnd <= currentScrollTop &&
        delta !== 0
      ) {
        currentScrollElement.scrollTop = Math.max(
          0,
          currentScrollElement.scrollTop + delta,
        );
        setViewport((current) => ({
          ...current,
          scrollTop: safeOffset(currentScrollElement.scrollTop),
        }));
      }

      forceVersion();
    },
    [safeCount, safeEstimateSize, scrollRef],
  );

  const measureRow = React.useCallback(
    (index: number, element: HTMLElement | null) => {
      if (!Number.isSafeInteger(index) || index < 0) return;

      const rowElements = rowElementsRef.current;
      const previousElement = rowElements.get(index);
      if (previousElement && previousElement !== element) {
        rowObserverRef.current?.unobserve(previousElement);
        observedIndexesRef.current.delete(previousElement);
        rowElements.delete(index);
      }

      if (!element) return;

      rowElements.set(index, element);
      observedIndexesRef.current.set(element, index);
      rowObserverRef.current?.observe(element);
      updateMeasuredSize(index, readElementHeight(element));
    },
    [updateMeasuredSize],
  );

  useKeyedLayoutEffect(
    joinEffectKey([scrollRef, scrollRef.current, scrollElement]),
    () => {
      const nextScrollElement = scrollRef.current;
      if (nextScrollElement !== scrollElement) {
        setScrollElement(nextScrollElement);
      }
    },
  );

  useKeyedLayoutEffect(
    joinEffectKey([scrollElement, updateMeasuredSize]),
    () => {
      if (typeof ResizeObserver === "undefined") return;

      const observer = new ResizeObserver((entries) => {
        for (const entry of entries) {
          const index = observedIndexesRef.current.get(
            entry.target as HTMLElement,
          );
          if (index == null) continue;
          updateMeasuredSize(index, readResizeEntryHeight(entry));
        }
      });

      rowObserverRef.current = observer;
      for (const element of rowElementsRef.current.values()) {
        observer.observe(element);
      }

      return () => {
        observer.disconnect();
        if (rowObserverRef.current === observer) rowObserverRef.current = null;
      };
    },
  );

  useKeyedLayoutEffect(
    joinEffectKey([scrollElement, initialViewportHeight]),
    () => {
      if (!scrollElement) {
        setViewport({ clientHeight: 0, scrollTop: 0 });
        return;
      }

      let frame = 0;
      const readViewport = () => {
        frame = 0;
        const next = {
          clientHeight: safeSize(scrollElement.clientHeight),
          scrollTop: safeOffset(scrollElement.scrollTop),
        };
        setViewport((current) =>
          current.clientHeight === next.clientHeight &&
          current.scrollTop === next.scrollTop
            ? current
            : next,
        );
      };
      const scheduleRead = () => {
        if (frame) return;
        frame = requestFrame(readViewport);
      };

      readViewport();
      scrollElement.addEventListener("scroll", scheduleRead, { passive: true });
      const observer =
        typeof ResizeObserver !== "undefined"
          ? new ResizeObserver(scheduleRead)
          : null;
      observer?.observe(scrollElement);

      return () => {
        if (frame) cancelFrame(frame);
        scrollElement.removeEventListener("scroll", scheduleRead);
        observer?.disconnect();
      };
    },
  );

  const rowSizes = React.useMemo(
    () => {
      void version;
      return Array.from(
        { length: safeCount },
        (_, index) => measuredSizesRef.current.get(index) ?? safeEstimateSize,
      );
    },
    [safeCount, safeEstimateSize, version],
  );
  const offsets = React.useMemo(
    () =>
      buildMeasuredRowOffsets({
        paddingEnd,
        paddingStart,
        rowSizes,
      }),
    [paddingEnd, paddingStart, rowSizes],
  );
  const viewportHeight =
    viewport.clientHeight ||
    safeSize(initialViewportHeight) ||
    safeEstimateSize;
  const virtualRows = React.useMemo(
    () =>
      getMeasuredRowVirtualItems({
        getItemKey,
        offsets,
        overscan,
        rowSizes,
        scrollTop: viewport.scrollTop,
        viewportHeight,
      }),
    [
      getItemKey,
      offsets,
      overscan,
      rowSizes,
      viewport.scrollTop,
      viewportHeight,
    ],
  );
  const virtualRowWindow = React.useMemo(
    () => measuredRowVirtualItemWindow(virtualRows),
    [virtualRows],
  );
  const scrollToIndex = React.useCallback(
    (index: number, options?: MeasuredRowScrollTarget) => {
      const currentScrollElement = scrollRef.current;
      if (!currentScrollElement) return;

      const top = measuredRowScrollTopForIndex({
        align: options?.align ?? "center",
        index,
        offsets: offsetsRef.current,
        rowSizes: rowSizesRef.current,
        viewportHeight: currentScrollElement.clientHeight || viewportHeight,
      });
      if (typeof currentScrollElement.scrollTo === "function") {
        currentScrollElement.scrollTo({
          behavior: options?.behavior ?? "smooth",
          top,
        });
      } else {
        currentScrollElement.scrollTop = top;
      }
      setViewport((current) => ({
        ...current,
        scrollTop: safeOffset(currentScrollElement.scrollTop),
      }));
    },
    [scrollRef, viewportHeight],
  );

  offsetsRef.current = offsets;
  rowSizesRef.current = rowSizes;

  return {
    measureRow,
    scrollToIndex,
    totalSize: offsets.totalSize,
    viewportClientHeight: viewportHeight,
    virtualRowWindow,
    virtualRows,
  };
}

function capMeasuredRowRange({
  count,
  end,
  maxItems,
  start,
  visibleEnd,
  visibleStart,
}: {
  count: number;
  end: number;
  maxItems: number;
  start: number;
  visibleEnd: number;
  visibleStart: number;
}) {
  const safeMaxItems = Math.max(1, safeCount(maxItems));
  if (end - start <= safeMaxItems) return [start, end] as const;

  const visibleCount = Math.min(
    safeMaxItems,
    Math.max(1, visibleEnd - visibleStart),
  );
  const leadingBudget = Math.floor((safeMaxItems - visibleCount) / 2);
  let cappedStart = Math.max(start, visibleStart - leadingBudget);
  let cappedEnd = Math.min(end, cappedStart + safeMaxItems);

  if (cappedEnd - cappedStart < safeMaxItems) {
    cappedStart = Math.max(start, cappedEnd - safeMaxItems);
  }
  if (cappedEnd < visibleEnd) {
    cappedEnd = Math.min(end, visibleEnd);
    cappedStart = Math.max(start, cappedEnd - safeMaxItems);
  }
  cappedEnd = Math.min(count, cappedEnd);

  return [cappedStart, cappedEnd] as const;
}

function findFirstRowEndingAfter({
  offset,
  rowSizes,
  starts,
}: {
  offset: number;
  rowSizes: readonly number[];
  starts: readonly number[];
}) {
  let low = 0;
  let high = rowSizes.length - 1;
  let result = rowSizes.length - 1;

  while (low <= high) {
    const middle = Math.floor((low + high) / 2);
    const end = (starts[middle] ?? 0) + safeSize(rowSizes[middle]);
    if (end > offset) {
      result = middle;
      high = middle - 1;
    } else {
      low = middle + 1;
    }
  }

  return result;
}

function findFirstRowStartingAtOrAfter({
  offset,
  starts,
}: {
  offset: number;
  starts: readonly number[];
}) {
  let low = 0;
  let high = starts.length - 1;
  let result = starts.length;

  while (low <= high) {
    const middle = Math.floor((low + high) / 2);
    if ((starts[middle] ?? 0) >= offset) {
      result = middle;
      high = middle - 1;
    } else {
      low = middle + 1;
    }
  }

  return result;
}

function readElementHeight(element: HTMLElement) {
  const rectHeight = element.getBoundingClientRect().height;
  if (Number.isFinite(rectHeight) && rectHeight > 0) return rectHeight;
  return element.offsetHeight;
}

function readResizeEntryHeight(entry: ResizeObserverEntry) {
  const borderBoxSize = entry.borderBoxSize;
  const boxSize = Array.isArray(borderBoxSize)
    ? borderBoxSize[0]
    : borderBoxSize;
  if (boxSize && Number.isFinite(boxSize.blockSize) && boxSize.blockSize > 0) {
    return boxSize.blockSize;
  }
  if (
    Number.isFinite(entry.contentRect.height) &&
    entry.contentRect.height > 0
  ) {
    return entry.contentRect.height;
  }
  return readElementHeight(entry.target as HTMLElement);
}

function requestFrame(callback: FrameRequestCallback) {
  if (typeof window !== "undefined" && window.requestAnimationFrame) {
    return window.requestAnimationFrame(callback);
  }
  return setTimeout(() => callback(performance.now()), 0) as unknown as number;
}

function cancelFrame(frame: number) {
  if (typeof window !== "undefined" && window.cancelAnimationFrame) {
    window.cancelAnimationFrame(frame);
    return;
  }
  clearTimeout(frame);
}

function measuredRowCount(count: number) {
  return Number.isFinite(count) && count > 0 ? Math.floor(count) : 0;
}

function safeCount(value: number) {
  return Number.isFinite(value) && value > 0 ? Math.floor(value) : 0;
}

function safeOffset(value: number) {
  return Number.isFinite(value) && value > 0 ? value : 0;
}

function safeSize(value: number | undefined) {
  return Number.isFinite(value) && value != null && value > 0 ? value : 0;
}

"use client";

import * as React from "react";

export type ArrayTableActiveCellStore = {
  getSnapshot: () => string | null;
  setActivePath: (path: string | null) => void;
  subscribe: (listener: () => void) => () => void;
};

export function createArrayTableActiveCellStore(): ArrayTableActiveCellStore {
  let activePath: string | null = null;
  const listeners = new Set<() => void>();

  return {
    getSnapshot: () => activePath,
    setActivePath: (path) => {
      if (activePath === path) return;
      activePath = path;
      listeners.forEach((listener) => listener());
    },
    subscribe: (listener) => {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
  };
}

export function useArrayTableCellActive(
  store: ArrayTableActiveCellStore,
  path: string,
): boolean {
  return React.useSyncExternalStore(
    store.subscribe,
    () => store.getSnapshot() === path,
    () => false,
  );
}

import type {
  DataCellProps,
  DataCellSelectOption,
} from "@/components/ui/data-cell";
import {
  dataCellNumberValue,
  dataCellTextValue,
  enumLabel,
  enumValueEquals,
} from "@/components/json-form/scalar-control";
import { NULL_SELECT_VALUE } from "@/components/json-form/scalar/enum-control";
import type { Column } from "@/components/json-form/schema-model";
import type { CommitArrayTableCellValue } from "@/components/json-form/table/array-table-cell-commit";
import type { ArrayTableCellModel } from "@/components/json-form/table/array-table-cell-model";
import { arrayTableCellProps } from "@/components/json-form/table/array-table-cell-props";

type ArrayTableDataCellSharedProps = {
  active: boolean;
  autoFocus: boolean;
  editable: boolean;
  name: string;
  onCommit: CommitArrayTableCellValue;
  onEditingEnd: () => void;
  role?: "button";
  tabIndex: 0;
  "aria-label": string;
  "data-table-cell-editable"?: "true";
  "data-table-cell-editor"?: "true";
  "data-table-cell-path"?: string;
};

export function createArrayTableDataCellProps({
  column,
  commitValue,
  isEditing,
  model,
  onEditingEnd,
}: {
  column: Column;
  commitValue: CommitArrayTableCellValue;
  isEditing: boolean;
  model: ArrayTableCellModel;
  onEditingEnd: () => void;
}): DataCellProps {
  const sharedProps = arrayTableDataCellSharedProps({
    commitValue,
    isEditing,
    model,
    onEditingEnd,
  });

  if (column.kind === "enum") {
    return arrayTableSelectDataCellProps({
      column,
      commitValue,
      model,
      sharedProps,
    });
  }

  if (model.kind === "number" || model.kind === "integer") {
    return {
      ...arrayTableCellProps(model, { isEditing }),
      ...sharedProps,
      kind: model.kind,
      value: dataCellNumberValue(model.value),
      formatValue: () => model.displayText,
      placeholder: "",
    };
  }

  if (model.kind === "boolean") {
    return {
      ...arrayTableCellProps(model, { isEditing }),
      ...sharedProps,
      kind: "boolean",
      value:
        model.value === null || model.value === undefined
          ? null
          : Boolean(model.value),
    };
  }

  if (model.kind === "date") {
    return {
      ...arrayTableCellProps(model, { isEditing }),
      ...sharedProps,
      kind: "date",
      value: dataCellTextValue(model.value),
      formatValue: () => model.displayText,
      placeholder: "",
    };
  }

  if (model.kind === "time") {
    return {
      ...arrayTableCellProps(model, { isEditing }),
      ...sharedProps,
      kind: "time",
      value: dataCellTextValue(model.value),
      formatValue: () => model.displayText,
      placeholder: "",
    };
  }

  if (model.kind === "date-time") {
    return {
      ...arrayTableCellProps(model, { isEditing }),
      ...sharedProps,
      kind: "date-time",
      value: dataCellTextValue(model.value),
      formatValue: () => model.displayText,
      placeholder: "",
    };
  }

  return {
    ...arrayTableCellProps(model, { isEditing }),
    ...sharedProps,
    kind: "text",
    value: dataCellTextValue(model.value),
    formatValue: () => model.displayText,
    placeholder: "",
  };
}

function arrayTableDataCellSharedProps({
  commitValue,
  isEditing,
  model,
  onEditingEnd,
}: {
  commitValue: CommitArrayTableCellValue;
  isEditing: boolean;
  model: ArrayTableCellModel;
  onEditingEnd: () => void;
}): ArrayTableDataCellSharedProps {
  return {
    active: isEditing,
    editable: isEditing,
    autoFocus: isEditing,
    name: model.path,
    onCommit: commitValue,
    onEditingEnd,
    role: isEditing ? undefined : "button",
    tabIndex: 0,
    "aria-label": `${model.label} ${model.displayText}`,
    "data-table-cell-editable": isEditing ? undefined : "true",
    "data-table-cell-editor": isEditing ? "true" : undefined,
    "data-table-cell-path": isEditing ? undefined : model.path,
  };
}

function arrayTableSelectDataCellProps({
  column,
  commitValue,
  model,
  sharedProps,
}: {
  column: Column;
  commitValue: CommitArrayTableCellValue;
  model: ArrayTableCellModel;
  sharedProps: ArrayTableDataCellSharedProps;
}): DataCellProps {
  return {
    ...arrayTableCellProps(model, { isEditing: sharedProps.active }),
    ...sharedProps,
    kind: "select",
    value: arrayTableSelectValue({
      column,
      value: model.value,
    }),
    selectOptions: arrayTableSelectOptions(column),
    placeholder: "Select...",
    formatValue: () => model.displayText,
    onCommit: (value, meta) => {
      commitValue(
        arrayTableSelectCommitValue({
          column,
          value,
        }),
        meta,
      );
    },
  };
}

function enumOptionValue(index: number): string {
  return `enum:${index}`;
}

function arrayTableSelectOptions(column: Column): DataCellSelectOption[] {
  const enumValues = column.schema.enum ?? [];
  const hasNullEnumValue = enumValues.some((value) => value === null);
  const nullableOptions: DataCellSelectOption[] =
    column.nullable && !hasNullEnumValue
      ? [{ value: NULL_SELECT_VALUE, label: "No value" }]
      : [];

  return [
    ...nullableOptions,
    ...enumValues.map((value, index) => ({
      value: enumOptionValue(index),
      label: enumLabel(value),
    })),
  ];
}

function arrayTableSelectValue({
  column,
  value,
}: {
  column: Column;
  value: unknown;
}): string | null {
  const enumIndex =
    column.schema.enum?.findIndex((candidate) =>
      enumValueEquals(candidate, value),
    ) ?? -1;

  if (enumIndex >= 0) return enumOptionValue(enumIndex);
  if (value === null && column.nullable) return NULL_SELECT_VALUE;
  return null;
}

function arrayTableSelectCommitValue({
  column,
  value,
}: {
  column: Column;
  value: string | null;
}): unknown {
  if (value === NULL_SELECT_VALUE || value === null) return null;
  const match = value.match(/^enum:(\d+)$/);
  if (!match) return undefined;
  return column.schema.enum?.[Number(match[1])];
}

"use client";

import * as React from "react";

type SourceLinkFocusModality = "none" | "keyboard" | "pointer";
type SourceLinkFocusIntentState = {
  modality: SourceLinkFocusModality;
};

const sourceLinkFocusIntentByDocument = new WeakMap<
  Document,
  SourceLinkFocusIntentState
>();

function isKeyboardFocusNavigation(event: KeyboardEvent): boolean {
  if (event.defaultPrevented || event.altKey || event.ctrlKey || event.metaKey) {
    return false;
  }
  return (
    event.key === "Tab" ||
    event.key === "ArrowDown" ||
    event.key === "ArrowLeft" ||
    event.key === "ArrowRight" ||
    event.key === "ArrowUp" ||
    event.key === "End" ||
    event.key === "Home" ||
    event.key === "PageDown" ||
    event.key === "PageUp"
  );
}

function getSourceLinkFocusIntentState(
  ownerDocument: Document,
): SourceLinkFocusIntentState {
  const existingState = sourceLinkFocusIntentByDocument.get(ownerDocument);
  if (existingState) return existingState;

  const state: SourceLinkFocusIntentState = { modality: "none" };
  sourceLinkFocusIntentByDocument.set(ownerDocument, state);

  ownerDocument.addEventListener(
    "keydown",
    (event) => {
      if (isKeyboardFocusNavigation(event)) state.modality = "keyboard";
    },
    true,
  );
  ownerDocument.addEventListener(
    "pointerdown",
    () => {
      state.modality = "pointer";
    },
    true,
  );
  ownerDocument.addEventListener(
    "mousedown",
    () => {
      state.modality = "pointer";
    },
    true,
  );
  ownerDocument.addEventListener(
    "touchstart",
    () => {
      state.modality = "pointer";
    },
    true,
  );

  return state;
}

export function useSourceLinkFocusPreviewIntent() {
  React.useEffect(() => {
    getSourceLinkFocusIntentState(document).modality = "none";
  }, []);

  return React.useCallback((event: React.FocusEvent<HTMLElement>): boolean => {
    if (event.defaultPrevented) return false;
    return (
      getSourceLinkFocusIntentState(event.currentTarget.ownerDocument)
        .modality === "keyboard"
    );
  }, []);
}
